for ix,g in enumerate(G):
    sources=OV.get(ix,next(v for ran,v in OWNERS.items() if ix in ran)); keys=D.get(ix,'').split();ns=[]
    for s in sources:
        for key in keys:
            if s=='RU-PREG': key={'renal_metric':'clcr','haemodialysis':'dialysis'}.get(key,key)
            if s=='RU-VENLA-XR' and key=='haemodialysis': key='dialysis'
            n=NORMS.get((s,key))
            if n:ns.append(dict(**n,source_sha256=S[s]['document_fingerprint']['sha256'],source_file='research/'+S[s]['local_file']))
    if ix in {79,80,81,163}:
        for s,k in [('RU-GAD','antidepressant_withdrawal_context'),('RU-DEP','antidepressant_withdrawal_context')]:
            if s in sources:ns.append(dict(**NORMS[(s,k)],source_sha256=S[s]['document_fingerprint']['sha256'],source_file='research/'+S[s]['local_file']))
    issue='LOCATOR_CC02' if ix in {20,21,26,28,99,100,128,129,132} else ('SOURCE_ATTRIBUTION_CC03' if ix in {150,151,161} else ('INTERNAL_PROSE_CC05' if ix==168 else None))
